function accountDeviceKind(){const ua=navigator.userAgent||'',appleTouch=navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1;return /iPhone|iPad|iPod|Android|Mobile/i.test(ua)||appleTouch?'mobile':'desktop'}
