function normalizedMarketSymbol(symbol){const value=String(symbol||'').toUpperCase().replace(/[-_]/g,'/');const base=value.replace(/\/(USDT|USDC)$/,'').replace(/(USDT|USDC)$/,'');return base?`${base}/USDT`:''}
