async function loadSymbolSuggestions(scope,query){const panel=byId(scope+'Suggestions'),requestId=++suggestionRequest,normalized=query.trim();if(!normalized){panel.innerHTML='';panel.classList.add('hidden');return}try{const response=await fetch('/api/symbol-suggestions?q='+encodeURIComponent(normalized));const data=await response.json();if(requestId!==suggestionRequest)return;panel.innerHTML=data.items.length?data.items.map(item=>`<button type="button" class="symbol-suggestion" onclick="selectSymbolSuggestion('${scope}','${item.symbol}','${item.label}')"><span>${item.name||item.symbol.split('/')[0]}</span><small>${item.symbol}${item.live?'':' · 暂无当前行情'}</small></button>`).join(''):'<p class="no-suggestion">没有匹配的币种</p>';panel.classList.remove('hidden')}catch(error){if(requestId!==suggestionRequest)return;panel.innerHTML='';panel.classList.add('hidden')}}
function closeSuggestionPanels(event){if(!event.target.closest('.search-suggest-wrap'))document.querySelectorAll('.search-suggest-wrap .symbol-suggestions').forEach(panel=>{panel.innerHTML='';panel.classList.add('hidden')});if(!event.target.closest('.thought-watch-add-search')){const panel=byId('thoughtWatchAddSuggestions');if(panel){panel.innerHTML='';panel.classList.add('hidden')}}}
document.addEventListener('click',closeSuggestionPanels)
function selectSymbolSuggestion(scope,symbol,label){const input=byId(scope+'Search');input.value=label;byId(scope+'Suggestions').classList.add('hidden');if(scope==='spotFutures'){spotFuturesSearch=symbol;spotFuturesPage=1;loadSpotFutures(true);return}dualFuturesSearch=symbol;dualFuturesPage=1;loadDualFutures(true)}
function setSpotFuturesSearch(value){spotFuturesSearch=value.trim();spotFuturesPage=1;loadSymbolSuggestions('spotFutures',value);clearTimeout(spotFuturesSearchTimer);spotFuturesSearchTimer=setTimeout(()=>loadSpotFutures(true),180)}
function setDualFuturesSearch(value){const query=value.trim();dualFuturesSearch=query;dualFuturesPage=1;loadSymbolSuggestions('dualFutures',query);clearTimeout(dualFuturesSearchTimer);dualFuturesSearchTimer=setTimeout(()=>loadDualFutures(true),180)}
function dualDisplayPercent(value){return value===null||value===undefined?'—':percent(value)}
function dualTrendLights(group){return `<div class="trend-lights">${trendPeriods.map(([key,label])=>`<span class="trend-light ${changeClass(group['binance_'+key])}" title="${label} ${displayChange(group['binance_'+key])}"><i></i><em>${label}</em></span>`).join('')}</div>`}
function dualPriceChanges(group){return `<div class="change-stack">${trendPeriods.map(([key,label])=>`<span class="change-item"><b>${label}</b><span class="${changeClass(group['binance_'+key])}">${displayChange(group['binance_'+key])}</span></span>`).join('')}</div>`}
function dualInterval(value){return value===null||value===undefined?'—':`${value}H`}
function dualMid(row,side){const bid=Number(row[`${side}_bid`]),ask=Number(row[`${side}_ask`]);return Number.isFinite(bid)&&Number.isFinite(ask)?(bid+ask)/2:null}
function marketPrice(value){const n=Number(value);if(!Number.isFinite(n))return '—';if(Math.abs(n)>=100)return n.toFixed(2);if(Math.abs(n)>=1)return n.toFixed(4);return n.toFixed(6)}
function fundingClock(value){const text=String(value||'--').trim();return text.includes(' ')?text.split(' ').pop():text}
function dualFundingCap(row,side){const cap=row[`${side}_funding_cap`]??row[`${side}_funding_upper`]??row[`${side}_funding_limit`];return cap===null||cap===undefined?'2%':dualDisplayPercent(cap)}
function dualFundingLine(row,side){const rate=row[`${side}_funding_rate`],next=fundingClock(row[`${side}_next_funding_time`]);return `<span class="dual-card-funding"><b>资费 / 上限 / 倒计时</b><em class="${changeClass(rate)}">${dualDisplayPercent(rate)}</em><i class="dual-sep">/</i><i class="dual-cap">${dualFundingCap(row,side)}</i><i class="dual-sep">/</i><small>${next}</small></span>`}
function dualCardLiquidity(oi,volume){return `<span class="dual-card-liquidity">${liquidityMetric('持仓量',oi)}<i>/</i>${liquidityMetric('24H量',volume)}</span>`}
function dualExchangeCard(row,side){const exchange=row[`${side}_exchange`],basis=row[`${side}_basis`],price=dualMid(row,side),oi=row[`${side}_open_interest`],volume=row[`${side}_volume`],label=side==='long'?'多':'空';return `<div class="dual-exchange-card ${side}"><header><span>${exchangeName(exchange)} <em>合约</em></span><div><i class="interval-badge ${intervalClass(row[`${side}_funding_interval_hours`])}">${dualInterval(row[`${side}_funding_interval_hours`])}</i><i class="dual-side ${side}">${label}</i></div></header><dl><div><dt>基差</dt><dd class="${changeClass(basis)}">${dualDisplayPercent(basis)}</dd></div>${dualFundingLine(row,side)}<div><dt>现价</dt><dd>${marketPrice(price)}</dd></div><div class="dual-liquidity-row"><dt>持仓量 / 24H交易量</dt><dd>${dualCardLiquidity(oi,volume)}</dd></div></dl></div>`}
function dualFundingDifference(row){return `<div class="${changeClass(row.funding_difference)} dual-funding-diff"><b>${dualDisplayPercent(row.funding_difference)}</b><small>${row.funding_settlement_label||'结算时间待同步'}</small></div>`}
const dualFundingDifferencePeriods=[['funding_difference','当前'],['funding_difference_previous','上期'],['funding_difference_24h','24H'],['funding_difference_3d','3D'],['funding_difference_7d','7D'],['funding_difference_30d','30D']];
function dualFundingHistory(row){return `<div class="dual-funding-history">${dualFundingDifferencePeriods.map(([key,label])=>`<span><b>${label}</b><em class="${changeClass(row[key])}">${dualDisplayPercent(row[key])}</em>${key==='funding_difference'?`<small>${row.funding_settlement_label||'待同步'}</small>`:''}</span>`).join('')}</div>`}
function ensureDualFundingHistoryHeader(){}
function dualLiquidity(row){return `<div class="liquidity-stack dual-liquidity"><span><b>多</b>${liquidityMetric('持仓量',row.long_open_interest)}${liquidityMetric('交易量',row.long_volume)}</span><span><b>空</b>${liquidityMetric('持仓量',row.short_open_interest)}${liquidityMetric('交易量',row.short_volume)}</span></div>`}
function componentMaps(row){return {long:Object.fromEntries((row.long_index_components||[]).map(item=>[item.source,item])),short:Object.fromEntries((row.short_index_components||[]).map(item=>[item.source,item]))}}
function localIndexOverlap(row){const {long,short}=componentMaps(row);return Object.keys(long).reduce((total,source)=>total+(short[source]?Math.min(Number(long[source].weight)||0,Number(short[source].weight)||0):0),0)*100}
function componentCompareRows(row){const {long,short}=componentMaps(row);return [...new Set([...Object.keys(long),...Object.keys(short)])].sort().map(source=>{const left=long[source],right=short[source],name=left?.name||right?.name,first=Number(left?.weight||0)*100,second=Number(right?.weight||0)*100;return `<article class="component-compare"><div><b>${name}</b><span>${row.long_exchange} ${first.toFixed(2)}% · ${row.short_exchange} ${second.toFixed(2)}%</span></div><div class="component-compare-bar"><i class="long" style="width:${first.toFixed(2)}%"></i><i class="short" style="width:${second.toFixed(2)}%"></i></div></article>`}).join('')}
function dualIndexOverlap(row){const longComponents=row.long_index_components||[],shortComponents=row.short_index_components||[];if(row.index_overlap===null||row.index_overlap===undefined)return `<span class="common-index-empty">${row.index_status||'成分待同步'}</span>`;if(!longComponents.length||!shortComponents.length)return '<span class="common-index-empty">指数成分不可用</span>';const overlap=Math.max(0,Math.min(100,localIndexOverlap(row)));return `<div class="common-index" data-common-index-id="${row._commonIndexId}"><b class="common-index-trigger" onmouseenter="showCommonIndexTip(this)" onmouseleave="destroyFloatingPopup()">${overlap.toFixed(2)}%</b></div>`}
function dualResultPanel(row){return `<div class="dual-result-panel"><div><span>开差</span><b class="${signClass(row.open_spread)}">${percent(row.open_spread)}</b></div><div><span>平差</span><b class="${signClass(row.close_spread)}">${percent(row.close_spread)}</b></div><div><span>共指</span>${dualIndexOverlap(row)}</div></div>`}
function dualRows(symbols){ensureDualFundingHistoryHeader();return symbols.map(group=>{const span=group.rows.length;return group.rows.map((row,index)=>`<tr class="${index===0?'dual-group-start ':index===span-1?'dual-group-end':'dual-group-body'}">${index===0?`<td class="symbol" rowspan="${span}">${dualTrendLights(group)}<div><button class="symbol-detail-trigger ${delistingSymbolClass(group.symbol,group.delisting_announced)}" data-market-symbol="${group.symbol}" data-delisting-announced="${group.delisting_announced?'1':'0'}" onclick="openSymbolDetail('${group.symbol}')">${group.symbol}</button><a class="kline-link" href="${coinglassKlineUrl(group.symbol)}" target="_blank" rel="noopener noreferrer">K线</a></div><div class="symbol-basis-opening">${basisOpeningMarkup(group.basis_opening,`dual:${group.symbol}`)}</div></td><td class="price-change-cell" rowspan="${span}">${dualPriceChanges(group)}</td>`:''}<td class="dual-leg-cell">${dualExchangeCard(row,'long')}</td><td class="dual-leg-cell">${dualExchangeCard(row,'short')}</td><td class="dual-result-cell">${dualResultPanel(row)}</td><td class="dual-funding-history-cell">${dualFundingHistory(row)}</td></tr>`).join('')}).join('')}
function dualRowsCompact(symbols){return symbols.map(group=>{const span=group.rows.length;return group.rows.map((row,index)=>{const shared=index===0?`<td class="symbol" rowspan="${span}">${dualTrendLights(group)}<div><button class="symbol-detail-trigger ${delistingSymbolClass(group.symbol,group.delisting_announced)}" data-market-symbol="${group.symbol}" data-delisting-announced="${group.delisting_announced?'1':'0'}" onclick="openSymbolDetail('${group.symbol}')">${group.symbol}</button><a class="kline-link" href="${coinglassKlineUrl(group.symbol)}" target="_blank" rel="noopener noreferrer">K线</a></div><div class="symbol-basis-opening">${basisOpeningMarkup(group.basis_opening,`dual:${group.symbol}`)}</div></td><td class="price-change-cell" rowspan="${span}">${dualPriceChanges(group)}</td>`:'';return `<tr data-render-key="dual|${group.symbol}|${row.long_exchange}|${row.short_exchange}" class="${index===0?'dual-group-start ':index===span-1?'dual-group-end':'dual-group-body'}">${shared}<td class="dual-leg-cell">${dualExchangeCard(row,'long')}</td><td class="dual-leg-cell">${dualExchangeCard(row,'short')}</td><td class="dual-result-cell"><div class="dual-result-stack">${dualResultPanel(row)}${dualFundingHistory(row)}</div></td></tr>`}).join('')}).join('')}
function positionFloatingPopup(popup,trigger){const rect=trigger.getBoundingClientRect(),width=Math.min(540,window.innerWidth-32),left=Math.max(16,Math.min(window.innerWidth-width-16,rect.right-width));popup.style.width=`${width}px`;popup.style.left=`${left}px`;if(rect.top<360){popup.style.top=`${rect.bottom+9}px`}else{popup.style.top=`${rect.top-9}px`;popup.style.transform='translateY(-100%)'}}
function destroyFloatingPopup(){document.querySelector('[data-floating-detail]')?.remove()}
function showCommonIndexTip(trigger){destroyFloatingPopup();const row=dualIndexRows.get(trigger.closest('.common-index')?.dataset.commonIndexId);if(!row)return;const overlap=Math.max(0,Math.min(100,localIndexOverlap(row))),popup=document.createElement('div'),path=`${row.long_exchange} → ${row.short_exchange}`;popup.dataset.floatingDetail='common-index';popup.className='floating-detail-popup common-index-popup';popup.innerHTML=`<header><span><i class="index-key long"></i>${exchangeName(row.long_exchange)}</span><b class="index-path">${path}</b><span><i class="index-key short"></i>${exchangeName(row.short_exchange)}</span></header><div class="component-compare-list">${componentCompareRows(row)}</div><div class="common-index-bar"><i style="width:${overlap.toFixed(2)}%"></i></div><small>共同成分权重 ${overlap.toFixed(2)}%</small>`;document.body.appendChild(popup);positionFloatingPopup(popup,trigger)}
function showDualRefreshCountdown(){clearInterval(dualMarketRefreshCountdownTimer);const target=byId('dualFuturesCountdown');if(target)target.textContent=''}
function dualSortPickerMarkup(){return `<div class="dual-sort-picker"><label><span>排序</span><select id="dualSortSelect" onchange="setDualSortFromPicker(this.value)">${dualSortOptions.map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label><button id="dualSortDirection" type="button" onclick="toggleDualSortDirection()">从高到低 ↓</button></div>`}
function configureDualLayoutShell(){const view=byId('dual-futures'),title=view?.querySelector('.panel-title>div:first-child'),resultHeader=view?.querySelector('.dual-result-header');if(title&&!byId('dualSortSelect')){title.classList.add('dual-title-group');title.querySelector('h2')?.insertAdjacentHTML('afterend',dualSortPickerMarkup())}view?.querySelector('.change-sort-controls')?.remove();view?.querySelector('.dual-result-sort-controls')?.remove();if(resultHeader?.querySelector('span'))resultHeader.querySelector('span').textContent='套利结果';updateDualSortHeaders()}
function updateDualSortHeaders(){document.querySelectorAll('.dual-sort-header').forEach(button=>{const active=button.dataset.dualSort===dualSort.key;button.classList.toggle('active',active);button.textContent=button.textContent.replace(/ [↕↓↑]$/,'')+(active?(dualSort.direction==='desc'?' ↓':' ↑'):'')});const select=byId('dualSortSelect'),direction=byId('dualSortDirection');if(select)select.value=dualSort.key;if(direction)direction.textContent=dualSort.direction==='desc'?'从高到低 ↓':'从低到高 ↑'}
function setDualSortFromPicker(key){if(!dualSortLabels[key])return;dualSort={key,direction:'desc'};dualFuturesPage=1;updateDualSortHeaders();loadDualFutures(true)}
function toggleDualSortDirection(){dualSort={key:dualSort.key,direction:dualSort.direction==='desc'?'asc':'desc'};dualFuturesPage=1;updateDualSortHeaders();loadDualFutures(true)}
function setDualSort(key){dualSort=dualSort.key===key?{key,direction:dualSort.direction==='desc'?'asc':'desc'}:{key,direction:'desc'};dualFuturesPage=1;updateDualSortHeaders();loadDualFutures(true)}
function setDualIncludeBybitOkx(checked){dualIncludeBybitOkx=!!checked;dualFuturesPage=1;loadDualFutures(true)}
function changeDualFuturesPage(change){dualFuturesPage=Math.max(1,dualFuturesPage+change);loadDualFutures(true)}
function selectDualFuturesPage(page){dualFuturesPage=Math.max(1,Number(page)||1);loadDualFutures(true)}
function renderDualFuturesShell(){const target=byId('dual-futures');target.innerHTML=`<div class="strategy-hero"><p class="eyebrow">STRATEGY 01 · FUTURES / FUTURES</p><h2>期多期空套利</h2><p>默认监控 Bybit → Binance 与 OKX → Binance；BY → OK 单独勾选后显示。做多交易所始终在左，做空交易所始终在右；趋势与涨跌幅统一参考 Binance 合约。</p><span class="mode-pill">后台每 5 秒更新 · 页面不闪烁</span></div><div class="panel"><div class="panel-title"><div><p class="eyebrow">LIVE FUTURES / FUTURES SCANNER</p><h2>期多期空机会</h2></div><div class="spot-actions"><label class="filter-check"><input id="dualIncludeBybitOkx" type="checkbox" onchange="setDualIncludeBybitOkx(this.checked)">显示 BY 对 OK</label><div class="search-suggest-wrap"><label class="search-control"><span>⌕</span><input id="dualFuturesSearch" type="search" autocomplete="off" placeholder="搜索币种，例如 BTC" oninput="setDualFuturesSearch(this.value)"></label><div id="dualFuturesSuggestions" class="symbol-suggestions hidden"></div></div><button onclick="loadDualFutures(true)">↻ 刷新数据</button></div></div><div class="table-wrap"><table class="dual-redesign-table"><thead><tr><th>交易对 / 趋势</th><th><div class="change-header"><span>涨跌幅</span><div class="change-sort-controls"><button class="dual-sort-header" data-dual-sort="binance_change_5m" onclick="setDualSort('binance_change_5m')">5MIN</button><button class="dual-sort-header" data-dual-sort="binance_change_15m" onclick="setDualSort('binance_change_15m')">15MIN</button><button class="dual-sort-header" data-dual-sort="binance_change_30m" onclick="setDualSort('binance_change_30m')">30MIN</button><button class="dual-sort-header" data-dual-sort="binance_change_1h" onclick="setDualSort('binance_change_1h')">1H</button><button class="dual-sort-header" data-dual-sort="binance_change_12h" onclick="setDualSort('binance_change_12h')">12H</button><button class="dual-sort-header" data-dual-sort="binance_change_24h" onclick="setDualSort('binance_change_24h')">24H</button><button class="dual-sort-header" data-dual-sort="binance_change_3d" onclick="setDualSort('binance_change_3d')">3D</button><button class="dual-sort-header" data-dual-sort="binance_change_7d" onclick="setDualSort('binance_change_7d')">7D</button></div></div></th><th>做多交易所</th><th>做空交易所</th><th><div class="dual-result-header"><span>套利结果 / 排序</span><div class="dual-result-sort-controls"><button class="dual-sort-header" data-dual-sort="open_spread" onclick="setDualSort('open_spread')">开差 ↓</button><button class="dual-sort-header" data-dual-sort="close_spread" onclick="setDualSort('close_spread')">平差</button><button class="dual-sort-header" data-dual-sort="funding_difference" onclick="setDualSort('funding_difference')">资费差</button><button class="dual-sort-header" data-dual-sort="binance_basis" onclick="setDualSort('binance_basis')">合约基差</button></div></div></th></tr></thead><tbody id="dualFuturesRows"><tr><td colspan="5" class="loading">正在连接三家交易所的公开合约行情…</td></tr></tbody></table></div><div class="pagination"><button id="dualPreviousPage" onclick="changeDualFuturesPage(-1)">← 上一页</button><label class="page-picker">跳至 <select id="dualFuturesPageSelect" onchange="selectDualFuturesPage(this.value)"></select> 页</label><span id="dualPageInfo">第 1 页</span><button id="dualNextPage" onclick="changeDualFuturesPage(1)">下一页 →</button></div><p class="data-status"><span id="dualFuturesUpdated"></span><span id="dualFuturesCountdown" class="refresh-countdown"></span></p></div>`}
async function loadDualFutures(manual=false){
  if(dualFuturesLoading||!byId('dualFuturesRows'))return false;
  dualFuturesLoading=true;const status=byId('dualFuturesUpdated'),emptyColspan=5;
  if(manual)status.textContent='正在读取后台已缓存的合约行情…';
  try{
    const data=await fetchRefreshJson('/api/dual-futures?page='+dualFuturesPage+'&symbol='+encodeURIComponent(dualFuturesSearch)+'&sort_by='+dualSort.key+'&sort_direction='+dualSort.direction+'&include_bybit_okx='+(dualIncludeBybitOkx?1:0));
    destroyFloatingPopup();dualBasisOpenings=Object.fromEntries(data.symbols.map(group=>[group.symbol,group.basis_opening]));dualIndexRows=new Map();
    data.symbols.forEach(group=>group.rows.forEach(row=>{row._commonIndexId=`${group.symbol}|${row.long_exchange}|${row.short_exchange}`;dualIndexRows.set(row._commonIndexId,row)}));
    replaceHtmlKeepingExchangeLogos(byId('dualFuturesRows'),data.symbols.length?dualRowsCompact(data.symbols):`<tr><td colspan="${emptyColspan}" class="loading">没有符合条件的合约路径。</td></tr>`);
    dualFuturesHasData=true;updateDualSortHeaders();byId('dualPageInfo').textContent=`第 ${data.page} / ${data.pages} 页 · 共 ${data.total_symbols} 个币种`;
    byId('dualFuturesPageSelect').innerHTML=Array.from({length:data.pages},(_,index)=>`<option value="${index+1}" ${index+1===data.page?'selected':''}>${index+1}</option>`).join('');
    byId('dualPreviousPage').disabled=data.page<=1;byId('dualNextPage').disabled=data.page>=data.pages;
    const byOkNote=data.include_bybit_okx?'含 BY→OK':'已过滤 BY→OK',failed=Object.keys(data.errors||{});
    status.textContent=`最近更新 ${data.updated_at} · ${byOkNote} · 全部 ${data.total_symbols} 币种排序 · ${dualSortLabels[dualSort.key]||dualSort.key} ${dualSort.direction==='desc'?'↓':'↑'}${failed.length?' · 部分上游沿用缓存':''}`;
    showDualRefreshCountdown();setPageRefreshSource('dual-futures',data.captured_at_epoch,'行情',failed.length>0);return true;
  }catch(error){
    if(!dualFuturesHasData)byId('dualFuturesRows').innerHTML=`<tr><td colspan="${emptyColspan}" class="loading">${escapeChatHtml(error.message)}</td></tr>`;
    status.textContent=dualFuturesHasData?`${error.message}，已保留上一组有效数据。`:error.message;return false;
  }finally{dualFuturesLoading=false}
}
function addDualLiquidityHeader(){const table=byId('dual-futures')?.querySelector('table');if(!table||table.classList.contains('dual-redesign-table'))return;const header=table.querySelector('thead tr');const changeHeader=header?.querySelector('.change-header')?.closest('th');if(changeHeader&&!header.querySelector('.liquidity-column')){const column=document.createElement('th');column.className='liquidity-column';column.textContent='流动性';changeHeader.insertAdjacentElement('afterend',column)}table.querySelectorAll('td[colspan="8"]').forEach(cell=>cell.colSpan=9)}
function addDualBasisSortControls(){const button=byId('dual-futures')?.querySelector('[data-dual-sort="binance_basis"]');if(!button||button.closest('.basis-sort-controls'))return;const wrapper=document.createElement('div');wrapper.className='basis-sort-controls';wrapper.innerHTML='<span>合约基差</span><div><button class="dual-sort-header" data-dual-sort="binance_basis" onclick="setDualSort(\'binance_basis\')">BN</button><button class="dual-sort-header" data-dual-sort="bybit_basis" onclick="setDualSort(\'bybit_basis\')">BY</button><button class="dual-sort-header" data-dual-sort="okx_basis" onclick="setDualSort(\'okx_basis\')">OK</button></div>';button.replaceWith(wrapper)}
function alertLabel(type){return type==='futures_pump'?'合约拉升':type==='spot_pump'?'现货拉升':type==='rapid_spread'?'开差速变':type==='rapid_basis'?'基差速变':type==='dual_spread_threshold'?'开差异动':type==='dual_basis_threshold'?'BN 基差异动':'基差异动'}
function alertClass(type){return type==='futures_pump'?'futures':type==='spot_pump'?'spot':type==='rapid_spread'?'rapid-spread':type==='rapid_basis'?'rapid-basis':'basis'}
function alertMetric(value){return value===null||value===undefined?'—':percent(value)}
function strategyLabel(strategy){return strategy==='futures_futures'?'期多期空':'现多期空'}
function alertExchangeLeg(exchange,market,interval){return `<span>${exchangeName(exchange)} ${market}${interval?` <em class="interval-badge ${intervalClass(interval)}">${interval}H</em>`:''}</span>`}
function alertExchangePair(item){return `<div class="alert-exchange-pair">${alertExchangeLeg(item.long_exchange,item.long_market,item.long_interval)}<b>→</b>${alertExchangeLeg(item.short_exchange,item.short_market,item.short_interval)}</div>`}
function toggleTips(){byId('tipsPanel').classList.toggle('collapsed')}
function isStandaloneWebApp(){return window.matchMedia?.('(display-mode: standalone)').matches||window.navigator.standalone===true}
function isAppleTouchDevice(){return /iPhone|iPad|iPod/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1)}
function chatPushSupported(){return 'serviceWorker'in navigator&&'PushManager'in window&&'Notification'in window}
function chatPushApplicationKey(value){const padding='='.repeat((4-value.length%4)%4),base64=(value+padding).replace(/-/g,'+').replace(/_/g,'/'),raw=atob(base64);return Uint8Array.from([...raw].map(character=>character.charCodeAt(0)))}
function renderChatPushState(text,action='',disabled=false){const gate=byId('chatPushGate'),label=byId('chatPushGateText'),button=byId('chatPushButton');if(!gate||!label||!button)return;gate.classList.remove('hidden');label.textContent=text;button.disabled=disabled;button.classList.toggle('hidden',!action);if(action==='disable'){button.textContent='关闭通知';button.onclick=disableChatPush}else if(action==='enable'){button.textContent='开启通知';button.onclick=enableChatPush}else{button.onclick=null}}
function chatPushJson(subscription){return subscription?.toJSON?subscription.toJSON():{endpoint:subscription?.endpoint||'',keys:{p256dh:'',auth:''}}}
async function saveChatPushSubscription(subscription){const response=await fetch('/api/chat/push/subscriptions',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':authState.csrf_token},body:JSON.stringify({subscription:chatPushJson(subscription)})}),data=await response.json();if(!response.ok)throw new Error(data.error||'系统通知订阅保存失败');return data}
async function setupChatPush(){if(chatPushSetupPromise)return chatPushSetupPromise;chatPushSetupPromise=(async()=>{if(!chatPushSupported()){if(isAppleTouchDevice())renderChatPushState(isStandaloneWebApp()?'当前 iOS 版本不支持网页系统通知':'请先将网页添加到主屏幕，再从主屏幕打开', '',true);return false}if(isAppleTouchDevice()&&!isStandaloneWebApp()){renderChatPushState('请先将网页添加到主屏幕，再从主屏幕打开','',true);return false}try{chatPushRegistration=await navigator.serviceWorker.register('/service-worker.js?v=20260815-web-push',{scope:'/'});const response=await fetch('/api/chat/push/config'),data=await response.json();if(!response.ok)throw new Error(data.error||'通知配置读取失败');chatPushConfig=data;if(!data.available||!data.public_key){renderChatPushState('服务器尚未启用系统通知','',true);return false}chatPushSubscription=await chatPushRegistration.pushManager.getSubscription();if(Notification.permission==='denied'){renderChatPushState('系统通知已关闭，请在系统设置中允许','',true);return false}if(chatPushSubscription&&Notification.permission==='granted'){await saveChatPushSubscription(chatPushSubscription);renderChatPushState('系统通知已开启，关闭网页后仍可提醒','disable');return true}renderChatPushState('关闭网页后也接收新的协作消息','enable');return true}catch(error){renderChatPushState(error.message||'系统通知暂时不可用','enable');return false}})();return chatPushSetupPromise}
async function enableChatPush(){if(!chatPushSupported()||!chatPushConfig?.available)return;const button=byId('chatPushButton');if(button)button.disabled=true;try{const permission=await Notification.requestPermission();if(permission!=='granted'){renderChatPushState(permission==='denied'?'系统通知已关闭，请在系统设置中允许':'需要允许系统通知后才能接收','enable',permission==='denied');return}chatPushSubscription=await chatPushRegistration.pushManager.getSubscription()||await chatPushRegistration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:chatPushApplicationKey(chatPushConfig.public_key)});await saveChatPushSubscription(chatPushSubscription);renderChatPushState('系统通知已开启，关闭网页后仍可提醒','disable')}catch(error){if(chatPushSubscription)await chatPushSubscription.unsubscribe().catch(()=>{});chatPushSubscription=null;renderChatPushState(error.message||'系统通知开启失败','enable')}}
async function disableChatPush(){const button=byId('chatPushButton');if(button)button.disabled=true;const subscription=chatPushSubscription||await chatPushRegistration?.pushManager.getSubscription();try{if(subscription){await fetch('/api/chat/push/subscriptions',{method:'DELETE',headers:{'Content-Type':'application/json','X-CSRF-Token':authState.csrf_token},body:JSON.stringify({subscription:chatPushJson(subscription)})});await subscription.unsubscribe()}chatPushSubscription=null;renderChatPushState('系统通知已关闭','enable')}catch(error){renderChatPushState(error.message||'系统通知关闭失败','disable')}}
function updateChatAudioGate(){const gate=byId('chatAudioGate'),label=byId('chatAudioGateText');if(!gate)return;const ready=chatSoundEnabled&&signalAudioPrimed&&alarmAudioContext?.state==='running',relevant=chatSoundEnabled||isStandaloneWebApp()||isAppleTouchDevice();gate.classList.toggle('hidden',!relevant||ready);if(label)label.textContent=chatSoundEnabled?'轻触开启本次协作声音':'协作声音当前已关闭'}
function updateSoundControls(){const alarm=byId('alarmSoundToggle'),chat=byId('chatSoundToggle');if(alarm)alarm.checked=alarmSoundEnabled;if(chat)chat.checked=chatSoundEnabled;updateChatAudioGate()}
async function ensureSignalAudioContext(){try{const AudioContextClass=window.AudioContext||window.webkitAudioContext;if(!AudioContextClass)return false;if(!alarmAudioContext||alarmAudioContext.state==='closed')alarmAudioContext=new AudioContextClass();if(alarmAudioContext.state==='suspended')await alarmAudioContext.resume();return alarmAudioContext.state==='running'}catch(error){return false}}
async function playSignalSound(enabled,force=false){if(!force&&!enabled)return false;try{if(!await ensureSignalAudioContext())return false;Array.from({length:12},(_,index)=>index*.125).forEach((offset,index)=>{const oscillator=alarmAudioContext.createOscillator(),gain=alarmAudioContext.createGain();oscillator.type='square';oscillator.frequency.value=index%2?880:1175;gain.gain.setValueAtTime(.0001,alarmAudioContext.currentTime+offset);gain.gain.exponentialRampToValueAtTime(.55,alarmAudioContext.currentTime+offset+.01);gain.gain.exponentialRampToValueAtTime(.0001,alarmAudioContext.currentTime+offset+.105);oscillator.connect(gain).connect(alarmAudioContext.destination);oscillator.start(alarmAudioContext.currentTime+offset);oscillator.stop(alarmAudioContext.currentTime+offset+.11)});return true}catch(error){return false}}
function playAlarmSound(force=false){return playSignalSound(alarmSoundEnabled,force)}
async function playChatSound(force=false){if(!force&&!chatSoundEnabled)return false;try{if(!await ensureSignalAudioContext()){signalAudioPrimed=false;updateChatAudioGate();return false}[[0,659.25],[.18,783.99]].forEach(([offset,frequency])=>{const oscillator=alarmAudioContext.createOscillator(),gain=alarmAudioContext.createGain(),start=alarmAudioContext.currentTime+offset;oscillator.type='sine';oscillator.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(.22,start+.018);gain.gain.exponentialRampToValueAtTime(.0001,start+.28);oscillator.connect(gain).connect(alarmAudioContext.destination);oscillator.start(start);oscillator.stop(start+.3)});signalAudioPrimed=true;chatSoundPending=false;updateChatAudioGate();return true}catch(error){signalAudioPrimed=false;updateChatAudioGate();return false}}
async function primeSignalAudio(){if(!alarmSoundEnabled&&!chatSoundEnabled){updateChatAudioGate();return false}if(signalAudioPrimed&&alarmAudioContext?.state==='running'){updateChatAudioGate();return true}try{if(!await ensureSignalAudioContext()){updateChatAudioGate();return false}const oscillator=alarmAudioContext.createOscillator(),gain=alarmAudioContext.createGain(),start=alarmAudioContext.currentTime;gain.gain.setValueAtTime(.00001,start);oscillator.connect(gain).connect(alarmAudioContext.destination);oscillator.start(start);oscillator.stop(start+.01);signalAudioPrimed=true;updateChatAudioGate();if(chatSoundPending&&chatSoundEnabled)return playChatSound();return true}catch(error){signalAudioPrimed=false;updateChatAudioGate();return false}}
async function activateChatAudio(){chatSoundEnabled=true;localStorage.setItem('arbi-chat-sound','on');signalAudioPrimed=false;updateSoundControls();const played=await playChatSound(true);if(!played){chatSoundPending=true;updateChatAudioGate()}return played}
function toggleAlarmSound(enabled){alarmSoundEnabled=Boolean(enabled);localStorage.setItem('arbi-alarm-sound',alarmSoundEnabled?'on':'off');updateSoundControls();if(alarmSoundEnabled)playAlarmSound()}
function toggleChatSound(enabled){if(enabled){activateChatAudio();return}chatSoundEnabled=false;chatSoundPending=false;signalAudioPrimed=false;localStorage.setItem('arbi-chat-sound','off');updateSoundControls()}
function testAlarmSound(){playSignalSound(true,true)}
function alertDeathMarkup(item){const expiresAt=Date.now()+Math.max(0,Number(item.remaining_seconds)||0)*1000;return `<small class="alert-death" data-alert-expires="${expiresAt}">${item.created_at} · 剩余 ${item.remaining_seconds}s</small>`}
function updateAlertCountdowns(){let expired=false;document.querySelectorAll('.alert-death').forEach(node=>{const remaining=Math.max(0,Math.ceil((Number(node.dataset.alertExpires)-Date.now())/1000));node.textContent=node.textContent.replace(/剩余 \d+s$/,`剩余 ${remaining}s`);if(remaining===0)expired=true});if(expired)loadAlerts(true)}
function startAlertCountdown(){clearInterval(alertCountdownTimer);updateAlertCountdowns();alertCountdownTimer=setInterval(updateAlertCountdowns,1000)}
function isAlertMuted(symbol){return mutedAlertSymbols.has(symbol)}
function alertActionSymbol(symbol){return escapeChatHtml(JSON.stringify(String(symbol)))}
function alertMuteButton(symbol){const muted=isAlertMuted(symbol);return `<button type="button" class="alert-mute-toggle ${muted?'muted':''}" onclick="toggleAlertMute(${alertActionSymbol(symbol)},event)" aria-label="${escapeChatHtml(symbol)} ${muted?'取消静音':'静音'}" aria-pressed="${muted}">${muted?'已静音':'静音'}</button>`}
function alertSpeakerButton(symbol){const muted=isAlertMuted(symbol);return `<button class="alert-speaker-toggle ${muted?'muted':''}" title="${muted?'取消静音':'静音'}" onclick="toggleAlertMute(${alertActionSymbol(symbol)},event)" aria-label="${muted?'取消静音':'静音'}"><span>${muted?'🔇':'🔊'}</span></button>`}
function pruneAlertMutes(groups,activeEvents){const visible=new Set([...(groups||[]).map(group=>group.symbol),...(activeEvents||[]).map(item=>item.symbol)]);[...mutedAlertSymbols].forEach(symbol=>{if(!visible.has(symbol))mutedAlertSymbols.delete(symbol)})}
function toggleAlertMute(symbol,event){event?.stopPropagation();if(isAlertMuted(symbol))mutedAlertSymbols.delete(symbol);else mutedAlertSymbols.add(symbol);renderAlertMasterDetail(latestAlertGroups);renderAlertMuteList();renderTipsItems(latestActiveAlertEvents)}
function renderAlertMuteList(){const target=byId('alertMuteList');if(!target)return;const muted=[...mutedAlertSymbols].sort();target.innerHTML=muted.length?muted.map(symbol=>`<button class="muted-symbol-pill" onclick="toggleAlertMute('${symbol}',event)">${symbol}<span>取消</span></button>`).join(''):'<p class="empty-alert">暂无静音币种。</p>'}
function alertTimelineNode(item){
  return `<li class="alert-timeline-node ${alertClass(item.type)}"><time>${escapeChatHtml(item.created_at)}</time><div class="alert-event-context"><b>${strategyLabel(item.strategy)} · ${alertLabel(item.type)}</b>${alertExchangePair(item)}</div><span class="alert-event-metric ${changeClass(item.open_spread)}" data-label="开差">${alertMetric(item.open_spread)}</span><span class="alert-event-metric ${changeClass(item.basis)}" data-label="基差">${alertMetric(item.basis)}</span></li>`;
}
function alertMetricRange(range){
  if(!Number.isFinite(range?.max)||!Number.isFinite(range?.min))return '<b class="alert-metric-range neutral">—</b>';
  return `<b class="alert-metric-range" aria-label="最高 ${alertMetric(range.max)}，最低 ${alertMetric(range.min)}"><span class="${changeClass(range.max)}">${alertMetric(range.max)}</span><span class="alert-range-separator" aria-hidden="true">～</span><span class="${changeClass(range.min)}">${alertMetric(range.min)}</span></b>`;
}
function alertTransferPanel(group){
  const priority=status=>transferHasRestriction(status)?0:status.state==='fresh'?1:status.state==='stale'?2:3;
  const statuses=(Array.isArray(group.transfer_statuses)?group.transfer_statuses:[]).filter(status=>status&&typeof status==='object').slice().sort((a,b)=>priority(a)-priority(b)),restricted=statuses.some(transferHasRestriction);
  return `<section class="alert-transfer-panel ${restricted?'has-restriction':''}" tabindex="0" role="region" aria-label="${escapeChatHtml(group.symbol)} 当前现货充提快照，非历史报警时状态" title="${restricted?'通道受限，价差需复核；':''}按交易所逐链显示该币种现货通道；独立同步，不随5秒行情实时更新；充提关闭不等同于公链停机或已确认价格脱钩"><div class="alert-transfer-exchanges">${statuses.length?statuses.map(status=>`<div class="alert-transfer-exchange"><b>${escapeChatHtml(status.exchange)}</b>${transferStatusMarkup(status)}</div>`).join(''):'<span class="transfer-data-note">充提未知 · 尚未读取</span>'}</div></section>`;
}
function alertDetailCard(group){
  const latest=group.latest,data=alertDetailState.symbol===group.symbol?alertDetailState.data:null,state=alertDetailState;
  return `<article class="alert-detail-card ${alertClass(latest.type)}" aria-label="${escapeChatHtml(group.symbol)} 报警明细"><div class="alert-detail-metrics"><span>最近开差 <b class="${changeClass(latest.open_spread)}">${alertMetric(latest.open_spread)}</b></span><span>最近基差 <b class="${changeClass(latest.basis)}">${alertMetric(latest.basis)}</b></span><span title="最近24小时确认报警的最高值～最低值">24H开差范围 ${alertMetricRange(group.value_ranges?.open_spread)}</span><span title="最近24小时确认报警中，币安合约标记价相对币安现货指数的基差最高值～最低值；不含币安合约的路径不参与">24H币安基差范围 ${alertMetricRange(group.basis_exchange==='Binance'?group.value_ranges?.basis:null)}</span></div>${alertTransferPanel(group)}<div class="alert-detail-status" role="status">${state.error?escapeChatHtml(state.error):''}</div><div class="alert-timeline-scroll" tabindex="0" role="region" aria-label="${escapeChatHtml(group.symbol)} 报警明细，可滚动"><div class="alert-timeline-head"><span>时间（UTC）</span><span>类型 / 交易路径</span><span>开差</span><span>基差</span></div><ol class="alert-timeline">${data?.items?.length?data.items.map(alertTimelineNode).join(''):`<li class="empty-alert">${state.error?'读取失败，可重试；已有记录不会被清除。':data?'最近24小时没有该币种的确认报警。':'正在读取该币种的报警时间线…'}</li>`}</ol></div><div class="alert-detail-pagination"><button type="button" onclick="loadSelectedAlertHistory(${Math.max(1,(data?.page||1)-1)},true)" ${!data||data.page<=1||state.loading?'disabled':''}>上一页</button><span>${data?`第 ${data.page} / ${data.pages} 页 · ${data.page_size}条/页`:'每页40条，全部可翻页'}</span><button type="button" onclick="loadSelectedAlertHistory(${(data?.page||1)+1},true)" ${!data||data.page>=data.pages||state.loading?'disabled':''}>下一页</button>${state.error?'<button type="button" onclick="loadSelectedAlertHistory()">重试</button>':''}</div></article>`;
}
function alertSymbolCard(group){
  const symbol=escapeChatHtml(group.symbol),peaks=group.move_peaks||{};
  return `<article class="alert-symbol-option ${group.symbol===selectedAlertSymbol?'active':''} ${alertClass(group.latest.type)} ${isAlertMuted(group.symbol)?'muted-alert':''}" data-alert-symbol="${symbol}"><div class="alert-symbol-cell"><button type="button" class="alert-coin-select ${delistingSymbolClass(group.symbol)}" data-market-symbol="${symbol}" onclick="selectAlertSymbol(${alertActionSymbol(group.symbol)})" aria-label="${symbol}，${group.alert_count}次报警，查看详情" aria-pressed="${group.symbol===selectedAlertSymbol}">${symbol}</button></div><span class="alert-symbol-count">${group.alert_count}</span><span class="alert-symbol-peak ${changeClass(peaks.open_spread)}">${alertMetric(peaks.open_spread)}</span><span class="alert-symbol-peak ${changeClass(peaks.basis)}">${alertMetric(peaks.basis)}</span>${alertMuteButton(group.symbol)}</article>`;
}
function visibleAlertGroups(groups=latestAlertGroups){
  const query=alertListQuery.toUpperCase().replace(/[\s/_-]/g,'');
  return groups.filter(group=>!query||group.symbol.toUpperCase().replace(/[/_-]/g,'').includes(query)).slice().sort((a,b)=>{
    if(alertListSort==='count')return b.alert_count-a.alert_count;
    if(['open_spread','basis'].includes(alertListSort))return Math.abs(b.move_peaks?.[alertListSort]??0)-Math.abs(a.move_peaks?.[alertListSort]??0);
    return 0;
  });
}
function alertRosterColumnsMarkup(){return '<div class="alert-roster-columns" aria-hidden="true"><span>币种</span><span>次数</span><span>开差峰值</span><span>基差峰值</span><span>静音</span></div>'}
function renderAlertRoster(){
  const groups=visibleAlertGroups(),list=byId('alertSymbolList');if(!list)return;
  const top=list.scrollTop;
  replaceHtmlKeepingExchangeLogos(list,alertRosterColumnsMarkup()+(groups.length?groups.map(alertSymbolCard).join(''):`<p class="empty-alert">${latestAlertGroups.length?'没有匹配的币种，清空搜索可查看全部。':'最近24小时暂无确认后的报警。'}</p>`));list.scrollTop=top;
  byId('alertRosterCount').textContent=alertListQuery?`${groups.length} / ${latestAlertGroups.length} 币`:`全部 ${latestAlertGroups.length} 币`;
  byId('alertTotalSymbols').textContent=latestAlertGroups.length;
  byId('alertTotalEvents').textContent=latestAlertGroups.reduce((sum,group)=>sum+group.alert_count,0);
  byId('alertActiveCount').textContent=latestActiveAlertEvents.length;
}
function filterAlertSymbols(value){alertListQuery=String(value||'');if(byId('alertSymbolList'))byId('alertSymbolList').scrollTop=0;renderAlertRoster()}
function sortAlertSymbols(value){alertListSort=['latest','count','open_spread','basis'].includes(value)?value:'latest';if(byId('alertSymbolList'))byId('alertSymbolList').scrollTop=0;renderAlertRoster()}
function renderAlertDetailPane(){
  const group=latestAlertGroups.find(item=>item.symbol===selectedAlertSymbol),pane=byId('alertDetailPane');if(!pane)return;
  const top=pane.querySelector('.alert-timeline-scroll')?.scrollTop||0;
  const transferTop=pane.dataset.alertSymbol===group?.symbol?pane.querySelector('.alert-transfer-panel')?.scrollTop||0:0;
  replaceHtmlKeepingExchangeLogos(pane,group?alertDetailCard(group):'<p class="empty-alert">选择左侧币种查看最近24小时的报警明细。</p>');
  pane.dataset.alertSymbol=group?.symbol||'';
  const scroll=pane.querySelector('.alert-timeline-scroll');if(scroll)scroll.scrollTop=top;
  const transferPanel=pane.querySelector('.alert-transfer-panel');if(transferPanel)transferPanel.scrollTop=transferTop;
}
function renderAlertMasterDetail(groups){
  latestAlertGroups=groups;
  if(!groups.some(group=>group.symbol===selectedAlertSymbol))selectedAlertSymbol=groups[0]?.symbol||'';
  if(alertDetailState.symbol!==selectedAlertSymbol){alertDetailVersion++;alertDetailState={symbol:selectedAlertSymbol,data:null,loading:false,error:''}}
  renderAlertRoster();renderAlertDetailPane();
}
function selectAlertSymbol(symbol){
  if(!latestAlertGroups.some(group=>group.symbol===symbol))return;
  selectedAlertSymbol=symbol;renderAlertMasterDetail(latestAlertGroups);loadSelectedAlertHistory(1,true);
  if(window.innerWidth<1100)byId('alertDetailPane')?.scrollIntoView({block:'start',behavior:'smooth'});
}
async function loadSelectedAlertHistory(page=alertDetailState.data?.page||1,resetScroll=false){
  const symbol=selectedAlertSymbol;if(!symbol)return false;
  const key=`${symbol}|${page}`;if(alertDetailRequest?.key===key)return alertDetailRequest.promise;
  const version=++alertDetailVersion;alertDetailState.loading=true;alertDetailState.error='';renderAlertDetailPane();
  const promise=(async()=>{try{
    const data=await fetchRefreshJson(`/api/alerts?${new URLSearchParams({view:'detail',symbol,page:String(page),page_size:'40'})}`);
    if(version!==alertDetailVersion||symbol!==selectedAlertSymbol)return false;
    if(data.symbol!==symbol||!Array.isArray(data.items)||data.items.some(item=>item.symbol!==symbol))throw new Error('明细币种不一致');
    alertDetailState.data=data;alertDetailState.loading=false;renderAlertDetailPane();
    if(resetScroll){const scroll=byId('alertDetailPane')?.querySelector('.alert-timeline-scroll');if(scroll)scroll.scrollTop=0}return true;
  }catch(error){if(version===alertDetailVersion&&symbol===selectedAlertSymbol){alertDetailState.loading=false;alertDetailState.error='明细读取失败，已保留上次记录，可重试。';renderAlertDetailPane()}return false}
  finally{if(alertDetailRequest?.version===version)alertDetailRequest=null}})();
  alertDetailRequest={key,version,promise};return promise;
}
function renderTipsItems(activeEvents){const target=byId('tipsItems');if(!target)return;target.innerHTML=activeEvents.length?activeEvents.map(item=>`<article class="tips-item ${alertClass(item.type)} ${isAlertMuted(item.symbol)?'muted-alert':''}"><div class="tips-item-head"><b class="${delistingSymbolClass(item.symbol)}" data-market-symbol="${item.symbol}">${item.symbol} · ${strategyLabel(item.strategy)} · ${alertLabel(item.type)}${isAlertMuted(item.symbol)?' · 已静音':''}</b>${alertSpeakerButton(item.symbol)}</div>${alertExchangePair(item)}<span>开差 ${alertMetric(item.open_spread)} · 基差 ${alertMetric(item.basis)}</span>${alertDeathMarkup(item)}</article>`).join(''):'<p class="empty-alert">当前没有处于 120 秒有效期的报警。</p>'}
async function loadAlerts(force=false){
  try{
    const data=await fetchRefreshJson('/api/alerts?view=summary'),activeEvents=data.active_events||[],groups=data.events||[],tracking=data.basis_tracking||[];
    pruneAlertMutes(groups,activeEvents);latestActiveAlertEvents=activeEvents;
    const signature=JSON.stringify({groups,tracking,activeEvents},(key,value)=>key==='remaining_seconds'?undefined:value);
    const audibleSignature=activeEvents.filter(item=>!isAlertMuted(item.symbol)).map(item=>`${item.symbol}-${item.type}-${item.open_spread}-${item.basis}-${item.created_at}`).join('|');
    const hasNewAlert=alertsInitialized&&audibleSignature!==alertAudibleSignature&&audibleSignature.length>0;
    setPageRefreshSource('alerts',data.checked_at_epoch,'检查');
    if(!force&&signature===alertSignature){if(activeViewId()==='alerts')loadSelectedAlertHistory();return true}
    renderAlertMasterDetail(groups);
    if(activeViewId()==='alerts')loadSelectedAlertHistory();
    replaceHtmlKeepingExchangeLogos(byId('basisTracking'),tracking.length?tracking.map(item=>`<article class="alert-item basis"><div class="alert-card-title"><h4>${item.symbol}</h4><span class="strategy-badge">${strategyLabel(item.strategy)} · 基差追踪</span></div><p class="tracking-max">最大 ${percent(item.max_basis)}</p><div class="meta"><span>已记录至 ${item.last_level.toFixed(1)}%</span><span>最大时间 ${item.max_at}</span></div></article>`).join(''):'<p class="empty-alert">暂无正在追踪的基差扩展。</p>');
    renderAlertMuteList();byId('tipsCount').textContent=activeEvents.length;renderTipsItems(activeEvents);startAlertCountdown();
    alertSignature=signature;alertAudibleSignature=audibleSignature;alertsInitialized=true;
    if(hasNewAlert)playAlarmSound();return true;
  }catch(error){
    if(!alertsInitialized){const list=byId('alertSymbolList');if(list)list.innerHTML='<p class="empty-alert">报警记录暂时无法读取，将自动重试。</p>';byId('tipsItems').innerHTML='<p class="empty-alert">报警暂时无法读取。</p>'}
    return false;
  }
}
function tokenHedgeList(items){return `<ul>${(items||[]).map(item=>`<li>${item}</li>`).join('')}</ul>`}
function tokenHedgeSources(items){return `<div class="token-hedge-sources">${(items||[]).map(item=>`<a target="_blank" rel="noopener noreferrer" href="${item.url}">${item.label}</a>`).join('')}</div>`}
async function loadTokenHedgeProfiles(){const target=byId('tokenHedgeProfiles');if(!target)return;target.innerHTML='<p class="loading">正在读取代币档案…</p>';try{const data=await (await fetch('/api/token-hedge/profiles')).json();target.innerHTML=data.profiles?.length?data.profiles.map(item=>`<article class="token-hedge-card ${item.risk_level==='极高'?'extreme':'high'}"><div class="token-hedge-head"><div><p class="eyebrow">${item.status}</p><h3 class="${delistingSymbolClass(item.symbol)}" data-market-symbol="${item.symbol}">${item.symbol}<span>${item.name}</span></h3></div><b>${item.risk_level}</b></div><section><h4>官方已确认</h4>${tokenHedgeList(item.official_facts)}</section><section class="token-hedge-thesis"><h4>盘口推演</h4><p>${item.market_thesis}</p></section><section><h4>盯盘规则</h4>${tokenHedgeList(item.watch_rules)}</section>${tokenHedgeSources(item.sources)}</article>`).join(''):'<p class="empty-alert">暂无代币档案。</p>'}catch(error){target.innerHTML='<p class="empty-alert">代币档案暂时无法读取。</p>'}}
function isDailyView(viewId){return ['daily-trends','daily-thoughts','daily-listings'].includes(viewId)}
function updateSidebarSubnav(viewId){document.querySelectorAll('aside .nav-sub').forEach(item=>item.classList.add('hidden'));document.querySelectorAll('aside nav a[data-subnav]').forEach(item=>item.classList.remove('expanded'));if(viewId==='spot-futures'){document.querySelector('aside .spot-period-nav')?.classList.remove('hidden');document.querySelector('aside nav a[data-subnav="spot-period-nav"]')?.classList.add('expanded')}if(isDailyView(viewId)){document.querySelector('aside .daily-nav')?.classList.remove('hidden');document.querySelector('aside nav a[data-subnav="daily-nav"]')?.classList.add('expanded')}}
function updateSidebarActive(link,viewId){document.querySelectorAll('nav a[data-view]').forEach(item=>{const parentSpot=item.dataset.subnav==='spot-period-nav'&&viewId==='spot-futures';const parentDaily=item.dataset.subnav==='daily-nav'&&isDailyView(viewId);item.classList.toggle('active',item===link||parentSpot||parentDaily)})}
