function ruleScheduleText(item){if(item.schedule_type==='toggle')return String(item.value)==='1'?'已隐藏':'正常显示';if(item.schedule_type==='daily_time')return `每天 ${item.value}`;if(item.schedule_type==='policy')return item.value;if(item.schedule_type==='retention')return `${item.value} ${item.unit}`;const seconds=Number(item.value);if(seconds>=3600&&seconds%3600===0)return `每 ${seconds/3600} 小时`;if(seconds>=60&&seconds%60===0)return `每 ${seconds/60} 分钟`;return `每 ${item.value} ${item.unit}`}
