async function createSymbolAlias(event){event.preventDefault();const body={canonical_base:byId('aliasCanonicalBase').value,alias_base:byId('aliasAlternateBase').value,exchange:byId('aliasExchange').value,market_type:byId('aliasMarketType').value,multiplier:byId('aliasMultiplier').value,note:byId('aliasNote').value},response=await fetch('/api/symbol-aliases',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':authState.csrf_token},body:JSON.stringify(body)}),data=await response.json();if(!response.ok){alert(data.error||'添加配对失败');return}byId('symbolAliasForm').reset();byId('aliasMultiplier').value='1';await loadSymbolAliases()}
