async function saveRuntimeRule(key){const input=document.querySelector(`[data-rule-value="${key}"]`),value=input.type==='checkbox'?(input.checked?'1':'0'):input.value,response=await fetch(`/api/runtime-rules/${key}`,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':authState.csrf_token},body:JSON.stringify({value,enabled:true})}),data=await response.json();if(!response.ok){alert(data.error||'保存失败');return}await loadAuthState();await loadRuntimeRules();startConfiguredPageTimers()}
async function createInviteCode(){const response=await fetch('/api/admin/invites',{method:'POST',headers:{'X-CSRF-Token':authState.csrf_token}}),data=await response.json();if(!response.ok){alert(data.error||'生成失败');return}const target=byId('newInviteCode');target.classList.remove('hidden');target.innerHTML=`<span>新邀请码（只显示这一次）</span><b>${data.code}</b><button onclick="navigator.clipboard.writeText('${data.code}')">复制</button><small>有效至 ${data.expires_at}</small>`;loadInviteHistory()}
async function loadInviteHistory(){const target=byId('inviteHistory');if(!target)return;const data=await (await fetch('/api/admin/invites')).json();target.innerHTML=data.items?.length?data.items.map(item=>`<span><b>${item.prefix}…</b><em class="${item.used?'used':''}">${item.used?'已使用':'等待使用'}</em><small>${item.expires_at||'长期有效'}</small></span>`).join(''):'<p class="empty-alert">还没有生成邀请码。</p>'}
function accountInviteStatus(item){if(item.status==='used')return ['已使用','used'];if(item.status==='expired')return ['已过期','expired'];return ['可使用','available']}
function accountInviteMarkup(item){const [label,state]=accountInviteStatus(item),shown=item.code||`${item.prefix}…`,copy=item.code?`<button onclick="navigator.clipboard.writeText('${item.code}')">复制</button>`:'',usage=item.used_by?`注册账号 <b>${item.used_by}</b> · ${item.used_at}`:(state==='available'?(item.code?'尚未注册':'历史邀请码仅保留前缀，请生成新码后使用'):`未使用 · ${item.expires_at||'—'}`);return `<article class="account-invite-item ${state}"><div class="account-invite-code"><code>${shown}</code><span>${label}</span>${copy}</div><p>${usage}</p><small>生成 ${item.created_at} · 有效至 ${item.expires_at||'长期有效'}</small></article>`}
function accountDeviceSlot(item,kind){const device=(item.devices||[]).find(entry=>entry.kind===kind),label=kind==='mobile'?'手机端':'电脑端',freeSwitch=!item.device_lock_required;if(!device)return `<article class="account-device-slot empty ${freeSwitch?'unenforced':''}"><div><b>${label}</b><em>${freeSwitch?'无需绑定':'未绑定'}</em></div><code>${freeSwitch?`${String(item.account_level||'').toUpperCase()} 可自由切换`:'等待该账号首次登录绑定'}</code><small>${freeSwitch?'当前等级不检查此设备槽位。':`绑定后，其他${label}即使密码正确也会被拒绝。`}</small></article>`;const current=device.current?'<span>当前设备</span>':'',client=escapeChatHtml(device.client_label||label),display=escapeChatHtml(device.display_id),sourceIp=escapeChatHtml(device.last_ip||'尚未记录'),sourceLocation=escapeChatHtml(device.last_location||'归属地待更新'),state=freeSwitch?'<em>当前不限制</em>':'';return `<article class="account-device-slot ${freeSwitch?'unenforced':''}"><div><b>${label}</b>${current}${state}<button type="button" onclick="unbindAccountDevice(${item.id},'${kind}',${device.current?'true':'false'})">解除绑定</button></div><code>${display}</code><small>${client} · 最近 IP ${sourceIp}<br>IP 归属地（约）${sourceLocation}<br>绑定 ${device.first_bound_at||'—'} · 最近登录 ${device.last_login_at||'—'}</small></article>`}
function accountLevelControl(item){const level=item.account_level||'lv1',admin=item.role==='admin',description=level==='lv3'?'最高权限，拥有全部管理功能。':level==='lv2'?'可用大部分功能，并可自由切换设备。':'可用基本功能，并启用电脑/手机设备保护。';if(admin)return `<label class="account-level-control fixed"><span>账号等级</span><select disabled><option>LV3 · 最高权限</option></select><small>${description} 管理员固定为 LV3。</small></label>`;return `<label class="account-level-control"><span>账号等级</span><select data-previous="${level}" onchange="setAccountLevel(${item.id},this)"><option value="lv1" ${level==='lv1'?'selected':''}>LV1 · 基本功能</option><option value="lv2" ${level==='lv2'?'selected':''}>LV2 · 大部分功能</option></select><small>${description}</small></label>`}
function accountUserMarkup(item){const username=escapeChatHtml(item.username),self=Number(item.id)===Number(authState.user_id),lastIp=escapeChatHtml(item.last_login_ip||'尚未记录'),lastLocation=escapeChatHtml(item.last_login_location||'归属地待更新'),accessButton=self?'<button type="button" disabled title="不能封禁当前登录的管理员">当前管理员</button>':`<button type="button" class="${item.active?'account-ban':'account-unban'}" onclick="setAccountActive(${item.id},${item.active?'false':'true'},this)">${item.active?'封禁账号':'解除封禁'}</button>`;return `<article class="account-user-item"><div><span class="account-avatar">${username.slice(0,1).toUpperCase()}</span><p><b>${username}</b><small>${item.role==='admin'?'管理员':'普通查看账号'}</small></p><em class="${item.active?'active':'disabled'}">${item.active?'可登录':'已封禁'}</em></div>${accountLevelControl(item)}<dl><div><dt>注册时间</dt><dd>${item.created_at||'—'}</dd></div><div><dt>最近登录</dt><dd>${item.last_login_at||'尚未登录'}</dd></div><div><dt>最近登录 IP</dt><dd>${lastIp}</dd></div><div><dt>IP 归属地（约）</dt><dd>${lastLocation}</dd></div><div><dt>密码更新</dt><dd id="accountPasswordChanged${item.id}">${item.password_changed_at||'尚未重置'}</dd></div></dl><div class="account-device-grid">${accountDeviceSlot(item,'desktop')}${accountDeviceSlot(item,'mobile')}</div><div class="account-security-actions"><div><button type="button" onclick="toggleAccountPasswordReset(${item.id})" ${item.active?'':'disabled'}>重置密码</button>${accessButton}</div><small>${item.active?'修改等级、封禁或重置密码都会让当前会话失效':'该账号当前无法登录'}</small></div><div id="accountPasswordReset${item.id}" class="account-password-reset hidden"><label>设置新密码<input id="accountNewPassword${item.id}" type="password" minlength="10" maxlength="128" autocomplete="new-password" placeholder="至少 10 位"></label><div><button type="button" onclick="resetAccountPassword(${item.id},'custom')">保存新密码</button><button type="button" onclick="resetAccountPassword(${item.id},'generate')">生成临时密码</button></div><p id="accountPasswordResult${item.id}"></p></div></article>`}
async function setAccountLevel(userId,select){const previous=select.dataset.previous||'lv1',level=select.value,detail=level==='lv2'?'LV2 可用大部分功能，并可在不同电脑或手机自由切换；新登录会替换上一次会话。':'LV1 可用基本功能，只允许已绑定的一台电脑和一台手机登录。';if(!confirm(`${detail}\n修改后该账号当前会话会立即失效，确定继续吗？`)){select.value=previous;return}select.disabled=true;try{const response=await fetch(`/api/admin/users/${userId}/account-level`,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':authState.csrf_token},body:JSON.stringify({account_level:level})}),data=await response.json();if(!response.ok)throw new Error(data.error||'账号等级修改失败');if(data.current_session_reset){alert('你的账号等级已修改，请重新登录。');location.href='/login';return}await loadAccountManagement()}catch(error){alert(error.message||'账号等级修改失败');select.value=previous;select.disabled=false}}
async function unbindAccountDevice(userId,kind,current=false){const label=kind==='mobile'?'手机端':'电脑端',warning=current?'这是你当前正在使用的设备，解除后会立即退出。':'';if(!confirm(`解除${label}绑定后，该账号下一次可以绑定新的${label}。${warning}\n确定继续吗？`))return;const response=await fetch(`/api/admin/users/${userId}/devices/${kind}`,{method:'DELETE',headers:{'X-CSRF-Token':authState.csrf_token}}),data=await response.json();if(!response.ok){alert(data.error||'解除设备绑定失败');return}if(data.current_session_unbound){location.href='/login';return}await loadAccountManagement()}
function securityAlertMarkup(item){return `<article class="security-alert-item ${item.read?'read':'unread'}"><span class="security-alert-icon">!</span><div><div><b>${escapeChatHtml(item.username)}</b><em>${escapeChatHtml(item.device_kind_label)}</em><time>${escapeChatHtml(item.created_at||'—')}</time></div><p>密码验证成功，但设备私钥与已绑定设备不一致，登录已拒绝。</p><code>${escapeChatHtml(item.attempted_device_id)}</code><small>${escapeChatHtml(item.client_label||'未知浏览器')} · 来源 IP ${escapeChatHtml(item.source_ip||'未知')} · IP 归属地（约）${escapeChatHtml(item.source_location||'待更新')}</small></div></article>`}
function updateSecurityAlertBadge(unread){const badge=byId('securityAlertBadge'),entry=document.querySelector('aside .security-nav-entry'),count=Number(unread)||0;badge?.classList.toggle('hidden',count===0);if(badge)badge.textContent=count>99?'99+':(count?String(count):'NEW');entry?.classList.toggle('security-attention',count>0)}
async function loadSecurityAlerts(markRead=false){const summary=byId('securityAlertSummary'),target=byId('securityAlertList');if(!authState.is_admin||!summary||!target)return;try{const response=await fetch('/api/admin/security-alerts'),data=await response.json();if(!response.ok)throw new Error(data.error||'安全通知读取失败');const unread=Number(data.unread)||0;updateSecurityAlertBadge(unread);summary.innerHTML=`<article><b>${data.items.length}</b><span>最近安全报告</span></article><article><b>${unread}</b><span>未读通知</span></article><article><b>已拦截</b><span>LV1 陌生设备不能登录</span></article>`;target.innerHTML=data.items.length?data.items.map(securityAlertMarkup).join(''):'<p class="empty-alert">暂时没有 LV1 账号的陌生设备登录报告。</p>';if(markRead&&unread){const readResponse=await fetch('/api/admin/security-alerts/read',{method:'POST',headers:{'X-CSRF-Token':authState.csrf_token}});if(readResponse.ok){updateSecurityAlertBadge(0);target.querySelectorAll('.security-alert-item.unread').forEach(item=>{item.classList.remove('unread');item.classList.add('read')})}}}catch(error){summary.innerHTML=`<p class="empty-alert">${escapeChatHtml(error.message||'安全通知暂时无法读取')}</p>`;target.innerHTML=''}}
function toggleAccountPasswordReset(userId){byId(`accountPasswordReset${userId}`)?.classList.toggle('hidden')}
async function setAccountActive(userId,active,button){const action=active?'解除封禁':'封禁',detail=active?'解封后，该账号可以重新登录。':'封禁后，该账号会立即退出，并且无法重新登录。';if(!confirm(`${detail}\n确定${action}吗？`))return;if(button)button.disabled=true;try{const response=await fetch(`/api/admin/users/${userId}/active`,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':authState.csrf_token},body:JSON.stringify({active})}),data=await response.json();if(!response.ok)throw new Error(data.error||`${action}失败`);await loadAccountManagement()}catch(error){alert(error.message||`${action}失败`);if(button)button.disabled=false}}
function showAccountPasswordResult(userId,data){const target=byId(`accountPasswordResult${userId}`);if(!target)return;target.innerHTML='';if(data.temporary_password){const label=document.createElement('span');label.textContent='一次性显示，请立即交给该账号：';const code=document.createElement('code');code.textContent=data.temporary_password;const copy=document.createElement('button');copy.type='button';copy.textContent='复制';copy.onclick=()=>navigator.clipboard.writeText(data.temporary_password);target.append(label,code,copy)}else{target.textContent='新密码已保存，原登录设备已退出。'}const changed=byId(`accountPasswordChanged${userId}`);if(changed)changed.textContent=data.password_changed_at||'刚刚'}
async function resetAccountPassword(userId,mode){const input=byId(`accountNewPassword${userId}`),newPassword=input?.value||'';if(mode==='custom'&&newPassword.length<10){alert('新密码至少需要 10 位。');input?.focus();return}const wording=mode==='generate'?'生成新的临时密码':'保存这个新密码';if(!confirm(`${wording}后，该账号当前登录设备会立即退出。确定继续吗？`))return;const response=await fetch(`/api/admin/users/${userId}/password`,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':authState.csrf_token},body:JSON.stringify(mode==='generate'?{mode:'generate'}:{new_password:newPassword})}),data=await response.json();if(!response.ok){alert(data.error||'密码重置失败');return}if(input)input.value='';showAccountPasswordResult(userId,data);if(Number(userId)===Number(authState.user_id)){alert('你的管理员密码已经更新，请使用新密码重新登录。');location.href='/login'}}
async function loadAccountManagement(){const summary=byId('accountSummary'),inviteTarget=byId('accountInviteList'),userTarget=byId('accountUserList');if(!summary||!inviteTarget||!userTarget)return;summary.classList.add('soft-loading');try{await loadAuthState();const [inviteResponse,userResponse]=await Promise.all([fetch('/api/admin/invites'),fetch('/api/admin/users')]);const invites=await inviteResponse.json(),users=await userResponse.json();if(!inviteResponse.ok||!userResponse.ok)throw new Error(invites.error||users.error||'账号数据读取失败');const lv1=users.items.filter(item=>item.account_level==='lv1').length,lv2=users.items.filter(item=>item.account_level==='lv2').length,lv3=users.items.filter(item=>item.account_level==='lv3').length;summary.innerHTML=`<article><b>${users.items.length}</b><span>全部账号</span></article><article><b>${lv1}</b><span>LV1 基本功能</span></article><article><b>${lv2}</b><span>LV2 大部分功能</span></article><article><b>${lv3}</b><span>LV3 最高权限</span></article>`;inviteTarget.innerHTML=invites.items.length?invites.items.map(accountInviteMarkup).join(''):'<p class="empty-alert">还没有邀请码，点击右上角生成第一个。</p>';userTarget.innerHTML=users.items.length?users.items.map(accountUserMarkup).join(''):'<p class="empty-alert">还没有账号记录。</p>'}catch(error){summary.innerHTML=`<p class="empty-alert">${error.message}</p>`;inviteTarget.innerHTML='';userTarget.innerHTML=''}finally{summary.classList.remove('soft-loading')}}
async function createAccountInviteCode(){await loadAuthState();const response=await fetch('/api/admin/invites',{method:'POST',headers:{'X-CSRF-Token':authState.csrf_token}}),data=await response.json();if(!response.ok){alert(data.error||'生成失败');return}const target=byId('accountNewInvite');target.classList.remove('hidden');target.innerHTML=`<span>新邀请码</span><b>${data.code}</b><button onclick="navigator.clipboard.writeText('${data.code}')">复制</button><small>仅能注册一次 · 有效至 ${data.expires_at}</small>`;await loadAccountManagement()}

function escapeChatHtml(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function isChatNetworkError(error){return error instanceof TypeError||/failed to fetch|networkerror|load failed|network request failed/i.test(String(error?.message||error||''))}
function chatRetryDelay(milliseconds){return new Promise(resolve=>setTimeout(resolve,milliseconds))}
function showChatNetworkStatus(text='网络短暂波动，正在自动恢复…'){const status=byId('chatSendStatus');if(!status||chatSendInFlight)return;status.dataset.networkStatus='1';status.textContent=text}
function clearChatNetworkStatus(){const status=byId('chatSendStatus');if(!status||status.dataset.networkStatus!=='1')return;delete status.dataset.networkStatus;status.textContent='内容仅在登录账号间可见 · 最多保留 7 天'}
async function chatFetch(url,options={},retries=2){let lastError;for(let attempt=0;attempt<=retries;attempt+=1){try{return await fetch(url,options)}catch(error){lastError=error;if(!isChatNetworkError(error)||attempt>=retries)throw error;showChatNetworkStatus();await chatRetryDelay(350*(attempt+1))}}throw lastError}
function handleChatBackgroundError(error){if(isChatNetworkError(error))showChatNetworkStatus()}
function chatDisplayName(item){return String(item?.remark||item?.display_name||item?.username||'')}
function chatPeerMarkup(item){const preview=item.last_message?escapeChatHtml(item.last_message):'还没有消息',badge=item.unread?`<em>${item.unread>99?'99+':item.unread}</em>`:'',displayName=escapeChatHtml(chatDisplayName(item)),accountPrefix=item.remark?`账号 ${escapeChatHtml(item.username)} · `:'';return `<div class="chat-peer ${item.id===chatPeerId?'active':''}" role="button" tabindex="0" onclick="selectChatPeer(${item.id})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();selectChatPeer(${item.id})}"><button type="button" class="chat-avatar chat-avatar-edit" onclick="openChatRemarkEditor(${item.id},event)" title="修改 ${escapeChatHtml(item.username)} 的备注" aria-label="修改 ${escapeChatHtml(item.username)} 的备注">${escapeChatHtml(item.username.slice(0,1).toUpperCase())}<span class="chat-avatar-edit-mark">✎</span></button><span class="chat-peer-copy"><b>${displayName} ${item.online?'<i>在线</i>':''}</b><small>${accountPrefix}${preview}</small></span><span class="chat-peer-meta"><time>${item.last_message_at||''}</time>${badge}</span></div>`}
function filteredChatUsers(){return chatUsers.filter(item=>!chatPeerQuery||item.username.toLowerCase().includes(chatPeerQuery)||chatDisplayName(item).toLowerCase().includes(chatPeerQuery))}
function newestChatMessage(items,predicate=()=>true){return (items||[]).filter(predicate).reduce((latest,item)=>(Number(item.last_message_id??item.id)||0)>(Number(latest?.last_message_id??latest?.id)||0)?item:latest,null)}
function newestChatMessageId(items,predicate=()=>true){const latest=newestChatMessage(items,predicate);return Number(latest?.last_message_id??latest?.id)||0}
function chatViewIsForeground(){return document.querySelector('.view.active')===byId('chat')&&document.visibilityState==='visible'&&document.hasFocus()}
function chatConversationIsForeground(peerId){const mobileConversationVisible=window.innerWidth>760||byId('chat')?.querySelector('.chat-shell')?.classList.contains('mobile-conversation-open');return chatViewIsForeground()&&mobileConversationVisible&&Number(peerId)===Number(chatPeerId)}
function announceIncomingChatMessage(messageId,senderId=0){const id=Number(messageId)||0;if(!id||id<=chatLastNotifiedIncomingId)return;chatLastNotifiedIncomingId=id;const chatActive=byId('chat')?.classList.contains('active');if(!chatActive)chatNavAttentionPending=true;updateChatNavAttention();if(!chatConversationIsForeground(senderId))playChatSound().then(played=>{if(!played&&chatSoundEnabled){chatSoundPending=true;updateChatAudioGate()}})}
function observeIncomingChatMessages(items,initial=false){const latestItem=newestChatMessage(items,item=>Number(item.recipient_id)===Number(authState.user_id)),latest=Number(latestItem?.id)||0;if(!latest)return;if(initial||!chatUnreadInitialized){chatLastNotifiedIncomingId=Math.max(chatLastNotifiedIncomingId,latest);return}announceIncomingChatMessage(latest,latestItem.sender_id)}
function renderChatUsers(data,force=false){chatUsers=data.items||[];const total=Number(data.unread_total)||0,target=byId('chatPeerList'),latestAny=newestChatMessageId(chatUsers),latestUnreadItem=newestChatMessage(chatUsers,item=>Number(item.unread)>0),latestUnread=Number(latestUnreadItem?.last_message_id)||0;if(!chatUnreadInitialized){chatLastNotifiedIncomingId=Math.max(chatLastNotifiedIncomingId,latestAny);chatNavAttentionPending=total>0&&!byId('chat')?.classList.contains('active')}else if(latestUnread>chatLastNotifiedIncomingId){announceIncomingChatMessage(latestUnread,latestUnreadItem.id)}chatUnreadTotal=total;chatUnreadInitialized=true;byId('chatUnreadSummary').textContent=`${total} 条未读`;updateChatNavAttention();const visible=filteredChatUsers(),signature=JSON.stringify([chatPeerId,chatPeerQuery,chatUsers.map(item=>[item.id,item.online,item.last_seen_at,item.last_message,item.last_message_at,item.last_message_id,item.unread,item.remark,item.display_name])]);if(!force&&signature===chatUsersSignature)return;chatUsersSignature=signature;target.innerHTML=visible.length?visible.map(chatPeerMarkup).join(''):(chatUsers.length?'<p class="chat-empty">没有匹配的账号。</p>':'<p class="chat-empty">目前没有其他可用账号。</p>')}
async function loadChatUsers(){
  if(chatUsersRequest)return chatUsersRequest;
  const task=(async()=>{const response=await chatFetch('/api/chat/users'),data=await response.json();if(!response.ok)throw new Error(data.error||'联系人读取失败');renderChatUsers(data);clearChatNetworkStatus();return data})();
  chatUsersRequest=task;
  try{return await task}finally{if(chatUsersRequest===task)chatUsersRequest=null}
}
function chatReceiptTitle(read,readAt){return read?`已读时间：${readAt||'历史时间未记录'}`:'对方尚未读取'}
function ensureChatActionUi(){const conversation=document.querySelector('.chat-conversation'),header=byId('chatConversationHeader'),inputWrap=document.querySelector('#chatComposer .chat-input-wrap');if(header&&!byId('chatPinnedBar'))header.insertAdjacentHTML('afterend','<div id="chatPinnedBar" class="chat-pinned-bar hidden"></div>');if(inputWrap&&!byId('chatReplyPreview'))inputWrap.insertAdjacentHTML('afterbegin','<div id="chatReplyPreview" class="chat-reply-preview hidden"></div>');if(!byId('chatMessageMenu'))document.body.insertAdjacentHTML('beforeend','<div id="chatMessageMenu" class="chat-message-menu hidden" role="menu"><button type="button" data-chat-action="reply" onclick="startChatReply()">↩ 引用</button><button type="button" data-chat-action="copy" onclick="copyChatMessage()">▣ 复制</button><button type="button" data-chat-action="pin" onclick="toggleChatMessagePin()">⌖ 置顶</button><button type="button" class="danger" data-chat-action="delete" onclick="deleteChatMessageForMe()">⌫ 删除</button><button type="button" class="danger" data-chat-action="recall" onclick="recallChatMessageForEveryone()">↶ 撤回</button></div>');if(!byId('chatActionConfirm'))document.body.insertAdjacentHTML('beforeend','<section id="chatActionConfirm" class="chat-confirm-overlay hidden" role="dialog" aria-modal="true"><div class="chat-confirm-card"><h3 id="chatConfirmTitle"></h3><p id="chatConfirmMessage"></p><label id="chatConfirmOption" class="chat-confirm-option hidden"><input id="chatConfirmCheckbox" type="checkbox"><i></i><span id="chatConfirmOptionText"></span></label><div class="chat-confirm-actions"><button type="button" onclick="resolveChatActionConfirm(false)">取消</button><button id="chatConfirmSubmit" type="button" class="danger" onclick="resolveChatActionConfirm(true)">确定</button></div></div></section>');if(conversation)conversation.classList.add('chat-actions-ready')}
function chatMessagePreview(item,limit=80){const body=String(item?.body||'').replace(/\s+/g,' ').trim();if(body)return body.length>limit?`${body.slice(0,limit)}…`:body;return item?.image?'[图片]':'消息'}
