function chatMessageMarkup(item){const mine=item.sender_id===authState.user_id;if(item.recalled)return `<article class="chat-message chat-recalled ${mine?'mine':'theirs'}" data-message-id="${item.id}"><span>${item.recalled_by_me?'你':'对方'}撤回了一条消息</span></article>`;const body=item.body?`<p>${escapeChatHtml(item.body).replace(/\n/g,'<br>')}</p>`:'',picture=item.image?`<a class="chat-message-image" href="${escapeChatHtml(item.image.url)}" target="_blank" rel="noopener" title="打开原图"><img src="${escapeChatHtml(item.image.url)}" alt="${escapeChatHtml(item.image.name||'聊天图片')}" loading="lazy"><span>${escapeChatHtml(item.image.name||'图片')} · ${chatFileSize(item.image.size)}</span></a>`:'',receiptTitle=chatReceiptTitle(item.read_by_peer,item.read_at),receipt=mine?`<span class="chat-read-state ${item.read_by_peer?'read':'unread'}" title="${escapeChatHtml(receiptTitle)}" aria-label="${escapeChatHtml(receiptTitle)}"><i aria-hidden="true"></i></span>`:'',pin=item.pinned?'<span class="chat-pin-mark" title="已置顶">⌖</span>':'';return `<article class="chat-message ${mine?'mine':'theirs'} ${item.pinned?'pinned':''}" data-message-id="${item.id}" tabindex="0" onclick="openChatMessageMenu(event,${item.id})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openChatMessageMenu(event,${item.id})}"><div>${chatReplyMarkup(item.reply)}${picture}${body}<footer><small class="chat-message-time">${escapeChatHtml(item.created_at)}</small>${pin}${receipt}</footer></div></article>`}
