async function jumpToChatMessage(messageId,event){event?.stopPropagation();const id=Number(messageId);let node=byId('chatMessages')?.querySelector(`[data-message-id="${id}"]`);if(!node){const status=byId('chatSendStatus');if(status)status.textContent='正在定位原消息…';try{await loadChatMessages('around',false,id)}catch(error){if(status)status.textContent=error.message||'原消息已删除或不在保留期';return}node=byId('chatMessages')?.querySelector(`[data-message-id="${id}"]`)}if(!node)return;node.scrollIntoView({behavior:'smooth',block:'center'});node.classList.remove('chat-message-flash');requestAnimationFrame(()=>node.classList.add('chat-message-flash'))}
