async function deleteChatMessageForMe(){const id=Number(chatMessageMenuId),item=chatMessageItems.get(id);if(!item)return;const mine=Number(item.sender_id)===Number(authState.user_id),peer=chatUsers.find(entry=>Number(entry.id)===Number(chatPeerId)),peerName=chatDisplayName(peer)||'对方',choice=await openChatActionConfirm({title:'您确定要删除此消息吗？',message:mine?'不勾选时，只从你自己的记录中删除。':'这条消息只会从你自己的记录中删除。',confirmText:'删除',optionText:mine?`同时为“${peerName}”撤回`:''});if(!choice.confirmed)return;const response=await fetch(`/api/chat/messages/${id}`,{method:'DELETE',headers:{'Content-Type':'application/json','X-CSRF-Token':authState.csrf_token},body:JSON.stringify({for_everyone:mine&&choice.checked})}),data=await response.json();if(!response.ok){alert(data.error||'删除失败');return}if(data.recalled&&data.item){applyRecalledChatMessage(data.item)}else{byId('chatMessages')?.querySelector(`[data-message-id="${id}"]`)?.remove();chatMessageItems.delete(id);applyUnavailableChatReference(id);if(chatReplyTarget?.id===id)clearChatReply();if(chatPinnedMessage?.id===id)renderChatPinnedBar(null);closeChatMessageMenu();if(!byId('chatMessages')?.querySelector('.chat-message'))byId('chatMessages').innerHTML='<p class="chat-empty">你这边还没有保留的聊天记录。</p>'}loadChatUsers().catch(handleChatBackgroundError)}
async function recallChatMessageForEveryone(){const id=Number(chatMessageMenuId),item=chatMessageItems.get(id);if(!item||Number(item.sender_id)!==Number(authState.user_id))return;const choice=await openChatActionConfirm({title:'确定撤回这条消息吗？',message:'撤回后双方都看不到原内容，聊天中会保留一条撤回提示。',confirmText:'撤回'});if(!choice.confirmed)return;const response=await fetch(`/api/chat/messages/${id}/recall`,{method:'POST',headers:{'X-CSRF-Token':authState.csrf_token}}),data=await response.json();if(!response.ok){alert(data.error||'撤回失败');return}applyRecalledChatMessage(data.item);loadChatUsers().catch(handleChatBackgroundError)}
function uniqueChatMessages(items){const unique=new Map();for(const item of items||[]){const id=Number(item?.id)||0;if(id)unique.set(id,item)}return [...unique.values()].sort((left,right)=>Number(left.id)-Number(right.id))}
function chatMessageIsRendered(id){return Boolean(byId('chatMessages')?.querySelector(`[data-message-id="${Number(id)}"]`))}
function updateChatReadReceipts(lastReadId,lastReadAt){const readThrough=Number(lastReadId)||0;document.querySelectorAll('#chatMessages .chat-message.mine[data-message-id]').forEach(node=>{const status=node.querySelector('.chat-read-state'),read=Number(node.dataset.messageId)<=readThrough;if(!status)return;const becameRead=read&&!status.classList.contains('read');status.classList.toggle('read',read);status.classList.toggle('unread',!read);if(becameRead||!read){const title=chatReceiptTitle(read,read?lastReadAt:null);status.title=title;status.setAttribute('aria-label',title)}})}
function appendNewChatMessages(rawItems,forceScroll=false){const target=byId('chatMessages');if(!target)return 0;const items=uniqueChatMessages(rawItems),nearBottom=target.scrollHeight-target.scrollTop-target.clientHeight<90,fresh=items.filter(item=>!chatMessageIsRendered(item.id));rememberChatMessages(items);if(fresh.length){target.querySelector('.chat-empty')?.remove();target.insertAdjacentHTML('beforeend',fresh.map(chatMessageMarkup).join(''))}if(items.length){chatLastMessageId=Math.max(chatLastMessageId,...items.map(item=>Number(item.id)));if(!chatOldestMessageId)chatOldestMessageId=Math.min(...items.map(item=>Number(item.id)))}if(fresh.length&&(forceScroll||nearBottom))scrollChatToBottom();return fresh.length}
function chatFileSize(size){const value=Number(size)||0;return value>=1024*1024?`${(value/1024/1024).toFixed(1)}MB`:`${Math.max(1,Math.round(value/1024))}KB`}
