function renderChatConversationHeader(peer){if(!peer||peer.id!==chatPeerId)return;const displayName=chatDisplayName(peer),account=peer.remark?`账号 ${peer.username} · `:'';byId('chatConversationHeader').innerHTML=`<button class="chat-mobile-back" type="button" onclick="showMobileChatPeers()" aria-label="返回协作者">‹</button><div><b>${escapeChatHtml(displayName)}</b><small>${escapeChatHtml(account)}${peer.role==='admin'?'管理员':'普通账号'} · ${escapeChatHtml(chatPresenceText(peer))}</small></div><button class="chat-clear" onclick="clearMyChatHistory()">清空我的记录</button>`}
