function updateChatHistoryBar(){const bar=byId('chatHistoryBar');if(!bar)return;bar.classList.toggle('hidden',!chatPeerId||!chatHasMoreBefore);const button=bar.querySelector('button');if(button){button.disabled=false;button.textContent='加载更早消息'}}
async function selectChatPeer(peerId){chatPeerId=Number(peerId);chatLastMessageId=0;chatOldestMessageId=0;chatHasMoreBefore=false;chatRecallCursor=0;chatUsersSignature='';chatMessageItems.clear();clearChatImage();clearChatReply();renderChatPinnedBar(null);closeChatMessageMenu();const peer=chatUsers.find(item=>item.id===chatPeerId);if(!peer)return;byId('chat')?.querySelector('.chat-shell')?.classList.add('mobile-conversation-open');syncMobileChatLayoutState();renderChatConversationHeader(peer);const input=byId('chatInput'),send=byId('chatComposer').querySelector('button[type="submit"]');input.disabled=false;send.disabled=false;byId('chatEmojiButton').disabled=false;byId('chatImageButton').disabled=false;byId('chatMessages').innerHTML='<p class="loading">正在读取消息…</p>';updateChatHistoryBar();renderChatUsers({items:chatUsers,unread_total:chatUsers.reduce((sum,item)=>sum+Number(item.unread||0),0)},true);try{await loadChatMessages('initial');await loadChatUsers()}catch(error){handleChatBackgroundError(error);byId('chatMessages').innerHTML=`<p class="chat-empty">${isChatNetworkError(error)?'网络刚刚闪断，正在自动恢复…':escapeChatHtml(error.message||'消息读取失败')}</p>`}startChatPolling();if(window.innerWidth>760)input.focus()}
async function loadChatMessages(mode='newer',forceScroll=false,aroundId=0){
  const requestedPeerId=Number(chatPeerId);
  if(!requestedPeerId)return;
  const params=new URLSearchParams();
  if(mode==='newer'&&chatLastMessageId)params.set('after_id',String(chatLastMessageId));
  if(mode==='older'&&chatOldestMessageId)params.set('before_id',String(chatOldestMessageId));
  if(mode==='around'&&aroundId)params.set('around_id',String(aroundId));
  if(chatRecallCursor)params.set('recalled_after_ms',String(chatRecallCursor));
  const query=params.toString()?`?${params}`:'';
  const requestKey=`${requestedPeerId}:${mode}:${query}`;
  if(chatMessageRequests.has(requestKey))return chatMessageRequests.get(requestKey);
  const task=(async()=>{
    const target=byId('chatMessages'),oldHeight=target.scrollHeight,oldTop=target.scrollTop;
    const response=await chatFetch(`/api/chat/messages/${requestedPeerId}${query}`),data=await response.json();
    if(!response.ok)throw new Error(data.error||'消息读取失败');
    if(Number(chatPeerId)!==requestedPeerId)return data;
    const items=uniqueChatMessages(data.items||[]);
    if(mode==='initial'||mode==='around'||(!chatLastMessageId&&mode!=='older')){
      observeIncomingChatMessages(items,true);
      rememberChatMessages(items,true);
      target.innerHTML=items.length?items.map(chatMessageMarkup).join(''):'<p class="chat-empty">你这边还没有保留的聊天记录。</p>';
      chatOldestMessageId=items[0]?.id||0;
      chatLastMessageId=items[items.length-1]?.id||0;
      chatHasMoreBefore=Boolean(data.has_more_before);
      if(mode==='initial')scrollChatToBottom();
    }else if(mode==='older'){
      const fresh=items.filter(item=>!chatMessageIsRendered(item.id));
      rememberChatMessages(items);
      if(fresh.length){target.querySelector('.chat-empty')?.remove();target.insertAdjacentHTML('afterbegin',fresh.map(chatMessageMarkup).join(''));chatOldestMessageId=Math.min(chatOldestMessageId||Infinity,...items.map(item=>Number(item.id)));requestAnimationFrame(()=>{target.scrollTop=target.scrollHeight-oldHeight+oldTop})}
      chatHasMoreBefore=Boolean(data.has_more_before);
    }else{
      observeIncomingChatMessages(items.filter(item=>!chatMessageIsRendered(item.id)));
      appendNewChatMessages(items,forceScroll);
    }
    for(const recalled of data.recalled_items||[])applyRecalledChatMessage(recalled);
    chatRecallCursor=Math.max(chatRecallCursor,Number(data.recall_cursor_ms)||0);
    if(data.pinned)rememberChatMessages([data.pinned]);
    renderChatPinnedBar(data.pinned||null);
    updateChatReadReceipts(data.peer_last_read_message_id,data.peer_last_read_at);
    updateChatHistoryBar();
    if(data.peer)renderChatConversationHeader(data.peer);
    clearChatNetworkStatus();
    return data;
  })();
  chatMessageRequests.set(requestKey,task);
  try{return await task}finally{if(chatMessageRequests.get(requestKey)===task)chatMessageRequests.delete(requestKey)}
}
async function loadOlderChatMessages(){if(!chatHasMoreBefore||!chatOldestMessageId)return;const button=byId('chatHistoryBar')?.querySelector('button');if(button){button.disabled=true;button.textContent='正在加载…'}try{await loadChatMessages('older')}catch(error){if(button){button.disabled=false;button.textContent='加载失败，点击重试'}}}
async function loadChat(force=false){try{await loadAuthState();await loadChatUsers();if(chatPeerId&&chatUsers.some(item=>item.id===chatPeerId))await loadChatMessages(force?'initial':'newer');else if(chatUsers.length&&window.innerWidth>760)await selectChatPeer(chatUsers[0].id);startChatPolling()}catch(error){handleChatBackgroundError(error);byId('chatPeerList').innerHTML=`<p class="chat-empty">${isChatNetworkError(error)?'网络刚刚闪断，正在自动恢复…':escapeChatHtml(error.message||'联系人读取失败')}</p>`}}
function startChatPolling(){clearInterval(chatPollTimer);clearInterval(chatMessagePollTimer);chatPollTimer=setInterval(()=>loadChatUsers().catch(handleChatBackgroundError),3000);chatMessagePollTimer=setInterval(()=>{if(byId('chat')?.classList.contains('active')&&chatPeerId)loadChatMessages('newer').catch(handleChatBackgroundError)},1000)}
function syncChatAfterWake(){if(!authState.user_id||document.visibilityState==='hidden')return;loadChatUsers().catch(handleChatBackgroundError);if(byId('chat')?.classList.contains('active')&&chatPeerId)loadChatMessages('newer').catch(handleChatBackgroundError)}
function updateChatComposer(){const input=byId('chatInput'),count=byId('chatCharCount');if(count)count.textContent=`${input?.value.length||0} / 2000`}
function toggleChatEmojiPicker(event){event?.stopPropagation();byId('chatEmojiPicker')?.classList.toggle('hidden')}
